<?php
class BookingController {private $m;private $j;public function __construct($p){$this->m=new Booking($p);$this->j=new Jadwal($p);}public function index(){$bookings=$this->m->allFor($_SESSION['user_role']==='admin'?null:$_SESSION['user_id']);include __DIR__.'/../views/booking/index.php';}public function form(){$jadwal=$this->j->all();include __DIR__.'/../views/booking/form.php';}public function save(){$id=(int)$_POST['jadwal_id'];$qty=max(1,(int)$_POST['jumlah_kursi']);$sisa=$this->j->availableSeats($id);$schedule=$this->j->find($id);if(!$schedule||$qty>$sisa){$_SESSION['flash']='Kursi tidak mencukupi';header('Location: index.php?page=booking-form');exit;}$kode='BKS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$this->m->create($_SESSION['user_id'],$id,$kode,$qty,$qty*$schedule['harga']);$_SESSION['flash']='Booking berhasil: '.$kode;header('Location: index.php?page=booking');exit;}public function cancel(){$this->m->cancel((int)$_GET['id'],$_SESSION['user_id']);$_SESSION['flash']='Booking dibatalkan';header('Location: index.php?page=booking');exit;}}
?>
